{'type': 'paragraph', 'children': [{'text': 'Step 1: ', 'bold': True}, {'text': 'Take the format of the application form from the '}, {'type': 'link', 'link': 'https://lidcom.co.in/contact.php', 'children': [{'text': 'District Office'}]}, {'text': ' of LIDCOM.'}]}
{'type': 'paragraph', 'children': [{'text': 'Step 2: ', 'bold': True}, {'text': 'Fill in all the mandatory fields, paste the passport sized photograph (signed across), and attach all the (self-attested) mandatory documents.'}]}
